import * as React from 'react';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Typography from '@mui/material/Typography';
import { Button, CardActionArea, CardActions } from '@mui/material';

export default function DefaultCard01() {
  return (
    <Card sx={{ maxWidth: "100%", height: "350px" }}>
      <CardActionArea>
        <CardMedia
          component="img"
          height="140"
          image="/static images/eye02.jpg"
          alt="green iguana"
        />
        <CardContent>
          <Typography gutterBottom variant="h5" component="div">
          Glaucoma 
          </Typography>
          <Typography variant="body2" color="text.secondary">
          **Retina Diseases -**  
          Explore retina diseases, a range of conditions affecting the light-sensitive tissue at the back of the eye, crucial for clear vision. Understand the causes, symptoms, and types of retina disorders such as diabetic retinopathy, macular degeneration, and retinal detachment. Discover the latest treatments, including medications, laser therapy, and surgical techniques, aimed at preserving and restoring vision. Early diagnosis and timely management are vital for maintaining eye health and preventing permanent vision impairment from these serious conditions.          </Typography>
        </CardContent>
      </CardActionArea>
    </Card>
  );
}
